-- Cleanup: the contact fields leave the KYC field set; rejected reviews that still name them lose them. The contact data itself is not
-- carried over: the system has not launched, local data comes from the dev seed.
UPDATE "seller"."kyc_reviews"
SET "required_fields" = array_remove(array_remove("required_fields", 'contact_email'), 'contact_phone')
WHERE 'contact_email' = ANY("required_fields") OR 'contact_phone' = ANY("required_fields");
-- Modify "kyc_applications" table
ALTER TABLE "seller"."kyc_applications" DROP CONSTRAINT "kyc_applications_contact_email_check", DROP CONSTRAINT "kyc_applications_contact_phone_check", DROP CONSTRAINT "kyc_applications_complete_check", ADD CONSTRAINT "kyc_applications_complete_check" CHECK ((status <> ALL (ARRAY['SUBMITTED'::text, 'APPROVED'::text, 'REJECTED'::text])) OR ((submitted_at IS NOT NULL) AND ((pii_purged_at IS NOT NULL) OR ((real_name IS NOT NULL) AND (english_name IS NOT NULL) AND (bank_name IS NOT NULL) AND (bank_code IS NOT NULL) AND (bank_account_enc IS NOT NULL) AND (((seller_type = 'INDIVIDUAL'::text) AND (id_card_no_enc IS NOT NULL)) OR ((seller_type = 'COMPANY'::text) AND (company_name IS NOT NULL) AND (tax_id IS NOT NULL) AND (rep_id_card_no_enc IS NOT NULL))))))), DROP CONSTRAINT "kyc_applications_purged_check", ADD CONSTRAINT "kyc_applications_purged_check" CHECK ((pii_purged_at IS NULL) OR ((real_name IS NULL) AND (birth_date IS NULL) AND (id_card_no_enc IS NULL) AND (id_card_hash IS NULL) AND (id_card_hash_key IS NULL) AND (id_card_issue_date IS NULL) AND (id_card_issue_type IS NULL) AND (id_card_issue_location IS NULL) AND (english_name IS NULL) AND (bank_name IS NULL) AND (bank_code IS NULL) AND (bank_account_enc IS NULL) AND (bank_account_hash IS NULL) AND (bank_account_hash_key IS NULL) AND (website_url IS NULL) AND (company_name IS NULL) AND (tax_id IS NULL) AND (tax_id_hash IS NULL) AND (tax_id_hash_key IS NULL) AND (company_register_date IS NULL) AND (company_town_code IS NULL) AND (company_address_detail IS NULL) AND (company_phone IS NULL) AND (rep_id_card_no_enc IS NULL) AND (rep_id_card_hash IS NULL) AND (rep_id_card_hash_key IS NULL))), DROP COLUMN "contact_email", DROP COLUMN "contact_phone";
-- Modify "payuni_registrations" table
ALTER TABLE "seller"."payuni_registrations" DROP CONSTRAINT "payuni_registrations_contact_mobile_check", DROP CONSTRAINT "payuni_registrations_contact_name_check", DROP CONSTRAINT "payuni_registrations_contact_tel_check", DROP CONSTRAINT "payuni_registrations_mer_email_check", DROP CONSTRAINT "payuni_registrations_mer_tel_check", DROP CONSTRAINT "payuni_registrations_version_check", DROP CONSTRAINT "payuni_registrations_purged_check", ADD CONSTRAINT "payuni_registrations_purged_check" CHECK ((pii_purged_at IS NULL) OR (reason IS NULL)), DROP COLUMN "contact_name", DROP COLUMN "contact_mobile", DROP COLUMN "contact_tel", DROP COLUMN "mer_email", DROP COLUMN "mer_tel", DROP COLUMN "version";
-- Modify "stores" table
ALTER TABLE "seller"."stores" DROP CONSTRAINT "stores_pii_purged_check", ADD CONSTRAINT "stores_pii_purged_check" CHECK (((pii_purged_at IS NULL) AND (store_name IS NOT NULL)) OR ((pii_purged_at IS NOT NULL) AND (status = 'CLOSED'::text) AND ((pii_purged_at - deleted_at) >= '30 days'::interval) AND (store_name IS NULL) AND (description IS NULL) AND (contact_phone IS NULL) AND (contact_name IS NULL) AND (contact_mobile IS NULL) AND (support_email IS NULL) AND (town_code IS NULL) AND (address_detail IS NULL) AND (prize IS NULL) AND (website_url IS NULL) AND (seo_title IS NULL) AND (seo_description IS NULL))), ADD CONSTRAINT "stores_contact_mobile_check" CHECK (contact_mobile ~ '^09[0-9]{8}$'::text), ADD CONSTRAINT "stores_contact_name_check" CHECK (char_length(contact_name) BETWEEN 1 AND 20 AND contact_name = btrim(contact_name)), ADD CONSTRAINT "stores_support_email_check" CHECK ((char_length(support_email) <= 50) AND (support_email = lower(support_email)) AND (support_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'::text)), ADD COLUMN "contact_name" text NULL, ADD COLUMN "contact_mobile" text NULL, ADD COLUMN "support_email" text NULL;
